    },
    {
      "name": "proximity_cluster",
      "analytical_usefulness": 0.9,
      "source_groundedness": 0.8,
      "hallucination_observed": false,
      "rationale": "Directly central to a query about regional location; sub-regional clustering is the key grouping axis. Derivable from Address/City/lat-long. Sand Hill Road->Peninsula-North is sound; '280 Group' at Santa Cruz Ave->East-Bay is questionable, otherwise well grounded."
    }
